CREATE TABLE "Lot" ("id" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "origin" TEXT NOT NULL DEFAULT '', "variety" TEXT NOT NULL DEFAULT '', "process" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT '?????????', "weight" DOUBLE PRECISION, "notes" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Lot_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Lot_code_key" ON "Lot"("code");
CREATE TABLE "Observation" ("id" TEXT NOT NULL, "lotId" TEXT NOT NULL, "type" TEXT NOT NULL, "value" TEXT NOT NULL, "unit" TEXT NOT NULL DEFAULT '', "source" TEXT NOT NULL DEFAULT '', "notes" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Observation_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Observation" ADD CONSTRAINT "Observation_lotId_fkey" FOREIGN KEY ("lotId") REFERENCES "Lot"("id") ON DELETE CASCADE ON UPDATE CASCADE;
